"use client";

import { useEffect, useMemo, useState, useTransition } from "react";
import { CalendarClock, Gauge, Gift, Shield, Sparkles, Swords, Trophy, Users, Zap } from "lucide-react";
import { toast } from "sonner";
import {
  adminCreateRushLeagueAction, adminFinishRushLeagueAction, adminGenerateRushDayAction,
  adminOpenRushLeagueAction, adminRunRushDayAction, adminUpdateRushLeagueAction,
  adminRegenerateRushRewardsAction, adminRerollRushRulesAction, adminSaveRushRewardsAction,
  adminDebugRushTeamAction, getRushDataAction, getRushScoutingAnalysisAction,
  joinRushLeagueAction, leaveRushLeagueAction, saveRushTeamAction,
} from "./actions";
import type { RushRewardBundle, RushRewardPlan } from "./constants";
import { RUSH_BATTLE_TIMES, RUSH_REWARD_TIME } from "./constants";
import { OFFICIAL_BATTLE_DIVISION_MODES } from "@/lib/battle-divisions";
import { CombatRoleHelpButton } from "@/components/combat-role-help";
import { TeamCombatAnalysisButton } from "@/components/team-combat-analysis";
import { LeagueBattleReplayModal, type TurnLog } from "@/app/(app)/combates/liga-semanal/_components/league-battle-replay";
import { OpponentAnalysisModal, type OpponentAnalysis } from "@/app/(app)/combates/liga-semanal/_components/league-client";
import { getStaticSpriteUrl } from "@/lib/mascot-data";
import { COMBAT_ROLE_OPTIONS, COMBAT_ROLE_DESCRIPTIONS, getCombatRoleLabel, recommendCombatRole, type CombatRole } from "@/lib/combat-roles";

type Mascot = { id:string; pokemonId:number; name:string; level:number; personality:string; types:string[]; statForce:number; statAgility:number; statInstinct:number; statVitality:number; statCharisma:number; megaEvolvedAt?:string|null; megaEvolvedFromPokemonId?:number|null };
type Participant = { id:string; playerId:string; points:number; wins:number; losses:number; draws:number; survivorsScore:number; damageDealt:number; damageTaken:number };
type Team = { battleDate:string; battleSlot:number; mascotIdsJson:string[];rolesJson?:Record<string,string>|null };
type Match = { id:string; battleDate:string; battleSlot:number; playerAId:string; playerBId?:string|null; winnerId?:string|null; isDraw:boolean; status:string; playerASurvivors:number; playerBSurvivors:number; replayJson?:TurnLog[]|null; resultJson?:{lineupA?:any[];lineupB?:any[]}|null };
type League = { id:string; name:string; weekKey:string; status:string; weekStart:string; weekEnd:string; registrationEnds:string; division:string; teamSize:number; maxLevel?:number|null; requiredType?:string|null; uniqueSpecies:boolean; participants:Participant[]; dailyTeams:Team[]; matches:Match[]; ruleJson?:Record<string,unknown> };
type Preset = { id:string; name:string; description:string; maxLevel:number; teamSize:number; uniqueSpecies:boolean; requiredType?:string|null; division?:string };
type Highlight = {id:string;name:string;pokemonId:number;ownerName:string;role:string;damageDealt:number;damageTaken:number;kosDealt:number;heals:number;attackActions:number;matches:number;wins:number};
type UpcomingLeague = Omit<League,"dailyTeams"|"matches">;
type Data = { league:League|null; isAdmin:boolean; playerId?:string; joined?:boolean; names?:Record<string,string>; mascots?:Mascot[]; today?:string; rewards?:RushRewardBundle[]; rewardPlan?:RushRewardPlan; rewardPlans?:RushRewardPlan[]; presets?:Preset[]; weekHighlights?:Highlight[]; cancellation?:{name:string;weekKey:string;ruleJson?:Record<string,unknown>;updatedAt:string}|null;upcomingRegistration?:UpcomingLeague|null;upcomingJoined?:boolean };

const TYPE_LABEL: Record<string,string> = { normal:"Normal",fire:"Fogo",water:"Água",electric:"Elétrico",grass:"Planta",ice:"Gelo",fighting:"Lutador",poison:"Veneno",ground:"Terra",flying:"Voador",psychic:"Psíquico",bug:"Inseto",rock:"Pedra",ghost:"Fantasma",dragon:"Dragão",dark:"Sombrio",steel:"Aço",fairy:"Fada" };
const PERSONALITY_LABEL:Record<string,string>={LOYAL:"Leal",PROUD:"Orgulhoso",MISCHIEVOUS:"Travesso",LAZY:"Preguiçoso",COMPETITIVE:"Competitivo",DRAMATIC:"Dramático",PLAYFUL:"Brincalhão",ELECTRIC:"Elétrico",TIMID:"Tímido",CHAOTIC:"Caótico"};
const STATUS_LABEL:Record<string,string>={REGISTRATION:"Registro",ACTIVE:"Em andamento",FINISHED:"Finalizada",CANCELLED:"Cancelada"};
const inputClass = "w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-xs text-white";
const cardClass = "rounded-2xl border border-slate-800 bg-slate-950/70 p-4";
const labelClass = "space-y-1 text-[10px] font-bold uppercase tracking-wide text-slate-400";
function addDaysIso(date:string,days:number){const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}
function localInput(value:string){const d=new Date(value);const shifted=new Date(d.getTime()-d.getTimezoneOffset()*60000);return shifted.toISOString().slice(0,16)}
function rangeLabel(r:RushRewardBundle){return r.rankTo&&r.rankTo!==r.rankFrom?`${r.rankFrom}º ao ${r.rankTo===9999?"último":`${r.rankTo}º`}`:`${r.rankFrom}º lugar`}

export function RushLeagueClient({initialData}:{initialData:Data}) {
  const [data,setData]=useState(initialData); const [pending,start]=useTransition(); const [selected,setSelected]=useState<Record<number,string[]>>({1:[],2:[],3:[]}); const [tab,setTab]=useState<"league"|"teams"|"results"|"rules"|"admin">("league");
  const run=(job:()=>Promise<{error?:string;success?:boolean}>)=>start(async()=>{
    try {
      const result=await job();
      if(result.error){toast.error(result.error);return;}
      const fresh=await getRushDataAction();
      setData(fresh as Data);
      toast.success("Operação concluída. Os dados da Rush já foram atualizados.");
    } catch(error) {
      toast.error(error instanceof Error?error.message:"A operação falhou. Tente novamente.");
    }
  });
  const league=data.league;
  if(!league)return <main className="mx-auto max-w-6xl space-y-6 px-4 py-8"><Header/>{data.cancellation&&<CancellationNotice cancellation={data.cancellation}/>}<RushManual presets={data.presets??[]}/>{data.isAdmin&&<CreatePanel data={data} run={run} pending={pending}/>}<DivisionTable/></main>;
  const names=data.names??{}; const teams=new Map((league.dailyTeams??[]).map(t=>[`${t.battleDate}:${t.battleSlot}`,t])); const activeRules=league.ruleJson??{}; const requiredPersonality=String(activeRules.requiredPersonality??""); const repetition=String(activeRules.repeatMode??(league.uniqueSpecies?"WEEKLY_UNIQUE":"UNRESTRICTED"));
  const eligible=(data.mascots??[]).filter(m=>(!league.maxLevel||m.level<=league.maxLevel)&&(!league.requiredType||m.types.includes(league.requiredType))&&(!requiredPersonality||m.personality===requiredPersonality));
  const registrationOpen=league.status==="REGISTRATION"&&Date.now()<=new Date(league.registrationEnds).getTime();
  return <main className="mx-auto max-w-6xl space-y-6 px-4 py-8">
    <Header division={league.division}/>
    {data.cancellation&&<CancellationNotice cancellation={data.cancellation}/>}
    {data.upcomingRegistration&&<UpcomingRegistration league={data.upcomingRegistration} joined={Boolean(data.upcomingJoined)} pending={pending} run={run}/>}
    <section className="rounded-2xl border border-orange-400/30 bg-gradient-to-br from-orange-950/50 to-slate-950 p-5">
      <div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[10px] font-black uppercase tracking-[.25em] text-orange-300">{league.weekKey} · {league.division==="LIMITED"?"Limitado":"Ilimitado"}</p><h2 className="mt-1 text-xl font-black text-white">{league.name}</h2><p className="mt-1 text-xs text-slate-400">Inscrição gratuita e opcional · partidas às 19:00, 19:10 e 19:20 · prêmios às 19:30</p></div><span className="rounded-full border border-orange-400/30 bg-orange-400/10 px-3 py-1 text-xs font-bold text-orange-200">{STATUS_LABEL[league.status]??league.status}</span></div>
      <div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-5"><Rule icon={<Users size={15}/>} label={`${league.teamSize} mascotes por combate`}/><Rule icon={<Gauge size={15}/>} label={league.maxLevel?`Nível máximo ${league.maxLevel}`:"Nível livre"}/><Rule icon={<Shield size={15}/>} label={league.division==="LIMITED"?"Limitado · máximo 2 Megas":"Ilimitado · Megas sem limite"}/><Rule icon={<Zap size={15}/>} label={league.requiredType?`Somente tipo ${TYPE_LABEL[league.requiredType]??league.requiredType}`:repetition==="WEEKLY_UNIQUE"?"Não repete na semana":repetition==="DAILY_UNIQUE"?"Não repete no mesmo dia":"Repetição livre"}/>{requiredPersonality&&<Rule icon={<Sparkles size={15}/>} label={`Personalidade ${PERSONALITY_LABEL[requiredPersonality]??requiredPersonality}`}/>}</div>
      <div className="mt-4">{data.joined?<button disabled={pending||!registrationOpen} onClick={()=>run(()=>leaveRushLeagueAction(league.id))} className="rounded-xl border border-red-400/40 px-4 py-2 text-xs font-bold text-red-300 disabled:opacity-40">Cancelar inscrição</button>:<button disabled={pending||!registrationOpen} onClick={()=>run(()=>joinRushLeagueAction(league.id))} className="rounded-xl bg-orange-400 px-5 py-2 text-xs font-black text-slate-950 disabled:opacity-40">Inscrever-se gratuitamente</button>}</div>
    </section>
    <div className="flex gap-1 overflow-x-auto">{[["league","Liga Atual","🏆"],["teams","Meus Times","👥"],["results","Resultados","📊"],["rules","Regras","📋"],...(data.isAdmin?[["admin","Admin","⚙️"]]:[])] .map(([id,label,emoji])=><button key={id} onClick={()=>setTab(id as typeof tab)} className={`shrink-0 rounded-xl px-3 py-1.5 text-xs font-semibold ${tab===id?"bg-orange-400/20 text-orange-300":"text-slate-400 hover:bg-slate-800"}`}>{emoji} {label}</button>)}</div>
    {tab==="league"&&<><RushTimeline league={league}/><ActiveChallenge league={league} presets={data.presets??[]}/><OwnAnalysis playerId={data.playerId} mascots={data.mascots??[]}/><Rewards plan={data.rewardPlan} rewards={data.rewards??[]} cap={Number(activeRules.rewardCap??6000)}/><div className="grid gap-6 lg:grid-cols-[1.3fr_.7fr]"><Ranking participants={league.participants} names={names} playerId={data.playerId}/><ScheduleCard/></div><MascotHighlights highlights={data.weekHighlights??[]}/></>}
    {tab==="teams"&&data.joined&&<TeamBuilder league={league} today={data.today!} eligible={eligible} teams={teams} selected={selected} setSelected={setSelected} run={run} pending={pending}/>}
    {tab==="teams"&&!data.joined&&<section className={cardClass}><p className="text-sm text-slate-400">Inscreva-se para montar as equipes desta semana.</p></section>}
    {tab==="results"&&<Matches matches={league.matches} names={names} playerId={data.playerId} mascots={data.mascots??[]}/>}
    {tab==="rules"&&<><RushManual presets={data.presets??[]}/><DivisionTable/></>}
    {tab==="admin"&&data.isAdmin&&<><AdminPanel league={league} data={data} run={run} pending={pending}/><RushTeamDebugger league={league} mascots={data.mascots??[]}/><CreatePanel data={data} run={run} pending={pending}/></>}
  </main>;
}

function Header({division}:{division?:string}){return <header><div className="flex flex-wrap items-center gap-2"><Zap className="text-orange-400"/><h1 className="text-2xl font-black text-white">Liga Semanal Rush</h1><span className="rounded-full bg-orange-400 px-2 py-0.5 text-[9px] font-black text-slate-950">CIRCUITO RÁPIDO</span>{division&&<span title={division==="LIMITED"?"Divisão Limitada: cada equipe pode ter no máximo 2 mascotes mega evoluídos.":"Divisão Ilimitada: não existe limite de mega evoluções na equipe."} className="cursor-help rounded-full border border-cyan-400/30 bg-cyan-400/10 px-2 py-0.5 text-[9px] font-black text-cyan-200">{division==="LIMITED"?"LIMITADO · MÁX. 2 MEGAS":"ILIMITADO · MEGAS LIVRES"}</span>}</div><p className="mt-1 text-sm text-slate-400">Uma nova semana, uma nova regra e equipes menores para testar ideias diferentes.</p></header>}
function Rule({icon,label}:{icon:React.ReactNode;label:string}){return <div className="flex items-center gap-2 rounded-xl border border-slate-800 bg-slate-950/70 px-3 py-2 text-xs text-slate-200">{icon}{label}</div>}
function brDate(value:string|Date,withTime=false){return new Intl.DateTimeFormat("pt-BR",{timeZone:"America/Sao_Paulo",day:"2-digit",month:"2-digit",...(withTime?{hour:"2-digit",minute:"2-digit"}: {})}).format(new Date(value))}
function UpcomingRegistration({league,joined,pending,run}:{league:UpcomingLeague;joined:boolean;pending:boolean;run:(job:()=>Promise<{error?:string;success?:boolean}>)=>void}){return <section className="rounded-2xl border border-cyan-400/30 bg-cyan-950/15 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-[10px] font-black uppercase tracking-[.2em] text-cyan-300">Próxima Rush · inscrições abertas</p><h2 className="mt-1 font-black text-white">{league.name}</h2><p className="mt-1 text-xs text-slate-400">Semana de {brDate(league.weekStart)} a {brDate(league.weekEnd)} · registro até {brDate(league.registrationEnds,true)}</p></div>{joined?<button disabled={pending} onClick={()=>run(()=>leaveRushLeagueAction(league.id))} className="rounded-xl border border-red-400/40 px-4 py-2 text-xs font-bold text-red-300">Cancelar registro</button>:<button disabled={pending} onClick={()=>run(()=>joinRushLeagueAction(league.id))} className="rounded-xl bg-cyan-400 px-5 py-2 text-xs font-black text-slate-950">Registrar-se na próxima Rush</button>}</div></section>}
function RushTimeline({league}:{league:League}){const date=brDate(league.weekStart);const events=[{label:"Fim do registro",date:brDate(league.registrationEnds),time:"07:50",color:"text-orange-300"},{label:"Chave e confirmação",date,time:"08:00",color:"text-cyan-300"},{label:"Combates diários",date:"Segunda a sexta",time:"19:00 · 19:10 · 19:20",color:"text-purple-300"},{label:"Fechamento da rodada",date:"Segunda a sexta",time:"19:30",color:"text-yellow-300"}];return <section className={cardClass}><h3 className="font-black text-white">🗓️ Próximos acontecimentos</h3><div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">{events.map(event=><div key={event.label} className="rounded-xl border border-slate-800 bg-slate-900/60 p-3"><p className="text-[9px] uppercase tracking-wide text-slate-500">{event.label}</p><p className="mt-1 text-xs text-slate-300">{event.date}</p><p className={`mt-1 text-base font-black ${event.color}`}>{event.time}</p></div>)}</div></section>}
function ActiveChallenge({league,presets}:{league:League;presets:Preset[]}){const rules=league.ruleJson??{};const preset=presets.find(item=>item.id===String(rules.preset??""));const repetition=String(rules.repeatMode??"UNRESTRICTED");const details=[preset?.description??"Edição personalizada: confira todos os limitadores abaixo.",league.maxLevel?`Nível: só entram mascotes até o nível ${league.maxLevel}.`:"Nível livre: qualquer nível pode participar.",league.requiredType?`Tipo: todo mascote escalado deve possuir o tipo ${TYPE_LABEL[league.requiredType]??league.requiredType}.`:"Tipos livres: não existe limitação elemental.",repetition==="WEEKLY_UNIQUE"?"Repetição semanal: o mesmo mascote só pode ser escalado uma vez durante toda a edição.":repetition==="DAILY_UNIQUE"?"Repetição diária: o mesmo mascote só pode jogar uma vez em cada dia.":"Repetição livre: o mesmo mascote pode aparecer em partidas diferentes.",league.division==="LIMITED"?"Divisão Limitada: no máximo 2 Megas na equipe.":"Divisão Ilimitada: não existe limite de Megas.",String(rules.requiredPersonality??"")?`Personalidade: apenas ${PERSONALITY_LABEL[String(rules.requiredPersonality)]??String(rules.requiredPersonality)} pode participar.`:"Personalidades livres."];return <section className="rounded-2xl border border-fuchsia-400/25 bg-fuchsia-950/10 p-4"><p className="text-[10px] font-black uppercase tracking-[.2em] text-fuchsia-300">Desafio desta semana</p><h3 className="mt-1 text-lg font-black text-white">{preset?.name??league.name}</h3><div className="mt-3 grid gap-2 md:grid-cols-2">{details.map((text,index)=><p key={index} className="rounded-xl border border-slate-800 bg-slate-950/60 p-3 text-[11px] leading-relaxed text-slate-300">{text}</p>)}</div></section>}
function OwnAnalysis({playerId,mascots}:{playerId?:string;mascots:Mascot[]}){const [analysis,setAnalysis]=useState<OpponentAnalysis|null>(null);const [pending,start]=useTransition();if(!playerId)return null;return <><div className="flex justify-end"><button disabled={pending} onClick={()=>start(async()=>{const response=await getRushScoutingAnalysisAction(playerId);if(response.error)toast.error(response.error);else setAnalysis(response.analysis as OpponentAnalysis)})} className="rounded-xl border border-cyan-400/25 bg-cyan-400/10 px-4 py-2 text-xs font-bold text-cyan-300 disabled:opacity-50">{pending?"Calculando...":"Ver análise própria"}</button></div>{analysis&&<OpponentAnalysisModal analysis={analysis} myMascots={mascots as any[]} showRecommendations={false} contextLabel="Liga Rush" onClose={()=>setAnalysis(null)}/>}</>}
function CancellationNotice({cancellation}:{cancellation:NonNullable<Data["cancellation"]>}){return <section className="rounded-2xl border border-red-400/35 bg-red-950/20 p-4"><h2 className="font-black text-red-200">Edição cancelada · {cancellation.name}</h2><p className="mt-1 text-sm text-red-100/80">{String(cancellation.ruleJson?.cancellationReason??"A edição não atingiu o mínimo de 4 jogadores inscritos até segunda-feira, 07:50.")}</p><p className="mt-2 text-xs text-slate-500">Uma nova edição automática será preparada apenas para a semana seguinte. Admins e GMs ainda podem iniciar uma edição manual.</p></section>}
const HIGHLIGHT_RULES=[{title:"Maior Dano",emoji:"⚔️",value:(h:Highlight)=>`${h.damageDealt.toLocaleString("pt-BR")} dano`,sort:(a:Highlight,b:Highlight)=>b.damageDealt-a.damageDealt},{title:"Mais KOs",emoji:"💀",value:(h:Highlight)=>`${h.kosDealt} KOs`,sort:(a:Highlight,b:Highlight)=>b.kosDealt-a.kosDealt},{title:"Mais Resistente",emoji:"🛡️",value:(h:Highlight)=>`${h.damageTaken.toLocaleString("pt-BR")} absorvido`,sort:(a:Highlight,b:Highlight)=>b.damageTaken-a.damageTaken},{title:"Melhor Cuidador",emoji:"💚",value:(h:Highlight)=>`${h.heals} curas`,sort:(a:Highlight,b:Highlight)=>b.heals-a.heals},{title:"Atacante Ágil",emoji:"💨",value:(h:Highlight)=>`${h.attackActions} ataques`,sort:(a:Highlight,b:Highlight)=>b.attackActions-a.attackActions},{title:"Mais Presente",emoji:"📅",value:(h:Highlight)=>`${h.matches} combates`,sort:(a:Highlight,b:Highlight)=>b.matches-a.matches}];
function MascotHighlights({highlights}:{highlights:Highlight[]}){if(!highlights.length)return null;return <section className={cardClass}><h3 className="font-black text-yellow-300">🌟 Destaques dos mascotes</h3><div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{HIGHLIGHT_RULES.map(rule=>{const top=[...highlights].sort(rule.sort)[0];if(!top||rule.value(top).startsWith("0 "))return null;return <div key={rule.title} className="flex items-center gap-3 rounded-xl border border-slate-800 p-3"><img src={getStaticSpriteUrl(top.pokemonId)} alt="" className="h-12 w-12 object-contain [image-rendering:pixelated]"/><div><p className="text-[10px] text-slate-500">{rule.emoji} {rule.title}</p><p className="text-xs font-black text-white">{top.name} <span className="font-normal text-slate-400">({top.ownerName})</span></p><p className="text-[10px] text-cyan-300">{rule.value(top)}</p></div></div>})}</div></section>}
function TeamBuilder({league,today,eligible,teams,run,pending}:{league:League;today:string;eligible:Mascot[];teams:Map<string,Team>;selected:Record<number,string[]>;setSelected:React.Dispatch<React.SetStateAction<Record<number,string[]>>>;run:(job:()=>Promise<{error?:string;success?:boolean}>)=>void;pending:boolean}){
  const [editing,setEditing]=useState<number|null>(null);const [picks,setPicks]=useState<string[]>([]);const [roles,setRoles]=useState<Record<string,string>>({});const [search,setSearch]=useState("");const [type,setType]=useState("");const [page,setPage]=useState(0);const perPage=12;const repetition=String(league.ruleJson?.repeatMode??(league.uniqueSpecies?"WEEKLY_UNIQUE":"UNRESTRICTED"));
  const open=(slot:number)=>{const saved=teams.get(`${today}:${slot}`);const ids=saved?.mascotIdsJson??[];setEditing(slot);setPicks(ids);setRoles({...saved?.rolesJson});setSearch("");setType("");setPage(0)};
  const unavailable=new Set([...teams.entries()].filter(([key])=>{const [date,slot]=key.split(":");if(Number(slot)===editing&&date===today)return false;return repetition==="WEEKLY_UNIQUE"||(repetition==="DAILY_UNIQUE"&&date===today)}).flatMap(([,team])=>team.mascotIdsJson));
  const filtered=eligible.filter(m=>(picks.includes(m.id)||!unavailable.has(m.id))&&(!search||m.name.toLowerCase().includes(search.toLowerCase()))&&(!type||m.types.includes(type)));const pages=Math.max(1,Math.ceil(filtered.length/perPage));const visible=filtered.slice(page*perPage,(page+1)*perPage);const chosen=picks.map(id=>eligible.find(m=>m.id===id)).filter(Boolean) as Mascot[];
  const toggle=(mascot:Mascot)=>{if(picks.includes(mascot.id)){setPicks(current=>current.filter(id=>id!==mascot.id));return}if(picks.length>=league.teamSize)return;const mega=Boolean(mascot.megaEvolvedAt||mascot.megaEvolvedFromPokemonId);const megaCount=chosen.filter(item=>item.megaEvolvedAt||item.megaEvolvedFromPokemonId).length;if(league.division==="LIMITED"&&mega&&megaCount>=2){toast.error("Divisão Limitada: esta equipe já possui 2 Megas.");return}setPicks(current=>[...current,mascot.id]);setRoles(current=>({...current,[mascot.id]:current[mascot.id]??recommendCombatRole(mascot as any)}))};
  if(editing)return <section className={cardClass}><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="font-black text-white">Montando Time {editing} · {RUSH_BATTLE_TIMES[editing-1]}</h3><div className="flex gap-2"><TeamCombatAnalysisButton mascots={chosen} roles={roles} mode="LEAGUE"/><button onClick={()=>setEditing(null)} className="text-xs text-slate-400">← Voltar</button></div></div><div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-6">{Array.from({length:league.teamSize},(_,index)=>{const mascot=chosen[index];const role=mascot?(roles[mascot.id]??recommendCombatRole(mascot as any)) as CombatRole:null;return <div key={index} className={`relative min-h-36 rounded-xl border p-2 ${mascot?"border-yellow-400/40 bg-yellow-400/10":"border-dashed border-slate-700"}`}><span className="absolute left-2 top-1 text-[9px] text-slate-500">{index+1}</span>{mascot?<div className="flex h-full flex-col items-center"><img src={getStaticSpriteUrl(mascot.pokemonId)} alt="" className="h-12 w-12 object-contain [image-rendering:pixelated]"/><p className="w-full truncate text-center text-[10px] font-bold text-white">{mascot.name}</p><p className="text-[9px] text-slate-500">Nv.{mascot.level}</p><select value={role??"ATTACKER"} onChange={event=>setRoles(current=>({...current,[mascot.id]:event.target.value}))} className="mt-1 w-full rounded border border-slate-700 bg-slate-950 p-1 text-[9px] text-yellow-300">{COMBAT_ROLE_OPTIONS.map(option=><option key={option.value} value={option.value}>{option.label}</option>)}</select><div className="mt-1 flex items-center gap-1"><CombatRoleHelpButton role={role} stats={mascot} teamStats={chosen} mode="LEAGUE" className="h-5 w-5"/><button onClick={()=>toggle(mascot)} className="text-[9px] text-red-300">Remover</button></div></div>:<p className="mt-14 text-center text-xs text-slate-700">vazio</p>}</div>})}</div>{chosen.length>0&&(()=>{const mascot=chosen.at(-1)!;const role=(roles[mascot.id]??recommendCombatRole(mascot as any)) as CombatRole;return <div className="mt-3 rounded-xl border border-slate-800 p-3"><strong className="text-xs text-yellow-300">{getCombatRoleLabel(role)}</strong><p className="mt-1 text-[10px] text-slate-400">{COMBAT_ROLE_DESCRIPTIONS[role]}</p></div>})()}<div className="mt-4 grid gap-2 sm:grid-cols-[1fr_220px]"><input value={search} onChange={e=>{setSearch(e.target.value);setPage(0)}} placeholder="Buscar mascote por nome..." className={inputClass}/><select value={type} onChange={e=>{setType(e.target.value);setPage(0)}} className={inputClass}><option value="">Todos os tipos</option>{Object.entries(TYPE_LABEL).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></div><div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-3">{visible.map(mascot=>{const checked=picks.includes(mascot.id);return <button key={mascot.id} onClick={()=>toggle(mascot)} className={`flex items-start gap-2 rounded-xl border p-3 text-left ${checked?"border-yellow-400/50 bg-yellow-400/10":"border-slate-800 bg-slate-900/50"}`}><img src={getStaticSpriteUrl(mascot.pokemonId)} alt="" className="h-12 w-12 object-contain [image-rendering:pixelated]"/><span className="min-w-0"><strong className="block truncate text-xs text-white">{mascot.name}</strong><small className="text-slate-500">Nv.{mascot.level} · {mascot.types.map(t=>TYPE_LABEL[t]??t).join("/")}</small><span className="mt-1 grid grid-cols-5 text-[8px] text-slate-400"><b>F{mascot.statForce}</b><b>A{mascot.statAgility}</b><b>C{mascot.statCharisma}</b><b>I{mascot.statInstinct}</b><b>V{mascot.statVitality}</b></span><small className="mt-1 block text-cyan-400">★ {getCombatRoleLabel(recommendCombatRole(mascot as any))}</small></span></button>})}</div>{pages>1&&<div className="mt-3 flex items-center justify-center gap-3"><button disabled={page===0} onClick={()=>setPage(current=>current-1)} className="rounded border border-slate-700 px-3 py-1 text-xs disabled:opacity-30">Anterior</button><span className="text-xs text-slate-500">{page+1}/{pages}</span><button disabled={page===pages-1} onClick={()=>setPage(current=>current+1)} className="rounded border border-slate-700 px-3 py-1 text-xs disabled:opacity-30">Próxima</button></div>}<button disabled={pending||picks.length<1} onClick={()=>run(()=>saveRushTeamAction({leagueId:league.id,battleDate:today,battleSlot:editing,mascotIds:picks,roles}))} className="mt-4 w-full rounded-xl bg-yellow-400 py-2.5 text-sm font-black text-slate-950 disabled:opacity-30">Salvar Time {editing} ({picks.length}/{league.teamSize})</button><p className="mt-2 text-center text-[10px] text-slate-500">É permitido salvar uma equipe incompleta, desde que tenha ao menos 1 mascote elegível.</p></section>;
  return <section className={cardClass}><div className="flex items-center justify-between"><div><h3 className="font-black text-white">Meus Times</h3><p className="mt-1 text-xs text-slate-400">Monte até três equipes para {brDate(today)}. As regras são conferidas novamente ao salvar.</p></div><CombatRoleHelpButton role="ATTACKER" mode="LEAGUE"/></div><div className="mt-3 rounded-xl border border-orange-400/20 bg-orange-400/5 p-3 text-[11px] text-orange-100"><strong>Regras ativas:</strong> até {league.teamSize} mascotes · {league.maxLevel?`Nv.${league.maxLevel} ou menos`:"nível livre"} · {league.division==="LIMITED"?"máximo 2 Megas":"Megas livres"} · {league.requiredType?`tipo ${TYPE_LABEL[league.requiredType]??league.requiredType}`:"todos os tipos"}.</div><div className="mt-4 space-y-3">{[1,2,3].map(slot=>{const saved=teams.get(`${today}:${slot}`);const mascots=(saved?.mascotIdsJson??[]).map(id=>eligible.find(m=>m.id===id)).filter(Boolean) as Mascot[];return <div key={slot} className="rounded-2xl border border-slate-800 bg-slate-900/50 p-4"><div className="flex items-center justify-between"><h4 className="text-xs font-bold text-slate-200">Time {slot} · Combate {RUSH_BATTLE_TIMES[slot-1]}</h4><button onClick={()=>open(slot)} className="rounded-lg border border-slate-700 px-3 py-1 text-[10px] text-slate-300">{mascots.length?"Editar":"Montar"}</button></div>{mascots.length?<div className="mt-3 grid grid-cols-3 gap-2 sm:grid-cols-6">{mascots.map(mascot=><div key={mascot.id} className="rounded-xl border border-yellow-400/20 bg-yellow-400/5 p-2 text-center"><img src={getStaticSpriteUrl(mascot.pokemonId)} alt="" className="mx-auto h-10 w-10 object-contain [image-rendering:pixelated]"/><p className="truncate text-[9px] text-white">{mascot.name}</p><p className="text-[8px] text-slate-500">Nv.{mascot.level}</p><p className="text-[8px] text-yellow-300">{getCombatRoleLabel((saved?.rolesJson?.[mascot.id]??recommendCombatRole(mascot as any)) as CombatRole)}</p></div>)}</div>:<p className="mt-3 text-[10px] text-slate-500">Nenhuma equipe montada.</p>}</div>})}</div></section>
}
function ScheduleCard(){return <section className={cardClass}><h3 className="flex items-center gap-2 font-black text-white"><CalendarClock size={16} className="text-cyan-300"/>Horários oficiais</h3><div className="mt-3 space-y-2 text-xs text-slate-300">{RUSH_BATTLE_TIMES.map((time,i)=><div key={time} className="flex justify-between rounded-lg border border-slate-800 px-3 py-2"><span>Partida {i+1}</span><strong className="text-cyan-300">{time}</strong></div>)}<div className="flex justify-between rounded-lg border border-yellow-400/30 bg-yellow-400/5 px-3 py-2"><span>Encerramento e distribuição</span><strong className="text-yellow-300">{RUSH_REWARD_TIME}</strong></div></div></section>}
function Ranking({participants,names,playerId}:{participants:Participant[];names:Record<string,string>;playerId?:string}){return <section className={cardClass}><h3 className="flex items-center gap-2 font-black text-white"><Trophy size={16} className="text-yellow-400"/>Classificação ({participants.length} jogadores)</h3><div className="mt-3 overflow-x-auto"><table className="w-full text-xs"><thead className="text-slate-500"><tr><th className="py-2 text-left">#</th><th className="text-left">Jogador</th><th>Pts</th><th>V</th><th>E</th><th>D</th><th>WO</th><th>Sobrev.</th><th>Dano+</th><th>Dano−</th><th>Hoje</th></tr></thead><tbody>{participants.map((p,i)=><tr key={p.id} className={`border-t border-slate-800 ${p.playerId===playerId?"bg-cyan-400/10 text-cyan-100":""}`}><td className="py-2 font-black text-yellow-300">{i+1}º</td><td className="font-bold text-white">{names[p.playerId]??p.playerId}</td><td className="text-center font-black text-cyan-300">{p.points}</td><td className="text-center text-green-300">{p.wins}</td><td className="text-center">{p.draws}</td><td className="text-center text-red-300">{p.losses}</td><td className="text-center text-slate-600">—</td><td className="text-center text-cyan-300">{p.survivorsScore}</td><td className="text-center">{p.damageDealt.toLocaleString("pt-BR")}</td><td className="text-center text-slate-500">{p.damageTaken.toLocaleString("pt-BR")}</td><td className="text-center text-slate-600">…</td></tr>)}</tbody></table></div></section>}
function Rewards({plan,rewards,cap=6000}:{plan?:RushRewardPlan;rewards:RushRewardBundle[];cap?:number}){return <section className="rounded-2xl border border-yellow-400/25 bg-gradient-to-r from-yellow-950/20 to-slate-950 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="flex items-center gap-2 font-black text-white"><Gift size={17} className="text-yellow-300"/>Prêmios desta semana · {plan?.name??"Pacote semanal"}</h3><p className="mt-1 text-xs text-slate-400">{plan?.description} As caixas chegam após o encerramento das 19:30 e são resgatadas nos Presentes.</p></div><span className="rounded-full border border-yellow-400/30 px-3 py-1 text-[10px] font-black text-yellow-300">TETO DE REFERÊNCIA: {cap.toLocaleString("pt-BR")} ZC</span></div><div className="mt-4 grid gap-2 md:grid-cols-2 xl:grid-cols-5">{rewards.map(r=><div key={r.key} className="rounded-xl border border-slate-800 bg-slate-950/70 p-3"><p className="text-[10px] font-black uppercase text-yellow-300">{rangeLabel(r)}</p><p className="mt-1 text-xs font-bold leading-relaxed text-white">{r.label}</p><p className="mt-2 text-[10px] text-slate-500">Valor estimado: até {r.estimatedValue.toLocaleString("pt-BR")} ZC</p></div>)}</div></section>}
function Matches({matches,names,playerId,mascots}:{matches:Match[];names:Record<string,string>;playerId?:string;mascots:Mascot[]}){const [replay,setReplay]=useState<Match|null>(null);const [analysis,setAnalysis]=useState<OpponentAnalysis|null>(null);const [pending,start]=useTransition();return <><section className={cardClass}><div className="flex items-center justify-between"><h3 className="flex items-center gap-2 font-black text-white"><Swords size={16}/>Resultados e chave</h3><span className="text-[10px] text-slate-500">Chave revelada diariamente às 08:00</span></div><div className="mt-3 grid gap-2 md:grid-cols-2">{matches.slice(0,60).map(m=>{const opponentId=playerId===m.playerAId?m.playerBId:playerId===m.playerBId?m.playerAId:null;return <div key={m.id} className="rounded-lg border border-slate-800 px-3 py-2 text-xs"><div className="flex justify-between text-slate-500"><span>{m.battleDate} · {RUSH_BATTLE_TIMES[m.battleSlot-1]}</span><span>{m.status==="RESOLVED"?"Finalizada":m.status==="SCHEDULED"?"Agendada":m.status}</span></div><p className="mt-1 font-bold text-white">{names[m.playerAId]??m.playerAId} × {m.playerBId?(names[m.playerBId]??m.playerBId):"Folga"}</p>{opponentId&&<button disabled={pending} onClick={()=>start(async()=>{const response=await getRushScoutingAnalysisAction(opponentId,m.id);if(response.error)toast.error(response.error);else setAnalysis(response.analysis as OpponentAnalysis)})} className="mt-2 rounded-lg border border-cyan-400/25 px-2 py-1 text-[10px] font-bold text-cyan-300">Analisar {names[opponentId]??"adversário"}</button>}{m.status==="RESOLVED"&&<div className="mt-1 flex items-center justify-between gap-2"><p className="text-cyan-300">{m.isDraw?"Empate":`Vencedor: ${names[m.winnerId??""]??"—"}`} · {m.playerASurvivors}–{m.playerBSurvivors}</p>{Array.isArray(m.replayJson)&&m.replayJson.length>0&&<button onClick={()=>setReplay(m)} className="rounded-lg border border-cyan-400/30 px-2 py-1 text-[10px] font-bold text-cyan-300">▶ Replay</button>}</div>}</div>})}</div>{!matches.length&&<p className="mt-3 text-xs text-slate-500">A chave desta rodada será revelada às 08:00. Nenhum confronto está disponível ainda.</p>}</section>{analysis&&<OpponentAnalysisModal analysis={analysis} myMascots={mascots as any[]} contextLabel="Liga Rush" onClose={()=>setAnalysis(null)}/>} {replay&&replay.playerBId&&<LeagueBattleReplayModal playerAName={names[replay.playerAId]??replay.playerAId} playerBName={names[replay.playerBId]??replay.playerBId} playerAId={replay.playerAId} winnerId={replay.winnerId} isDraw={replay.isDraw} replay={replay.replayJson??[]} playerASurvivors={replay.playerASurvivors} playerBSurvivors={replay.playerBSurvivors} lineupA={replay.resultJson?.lineupA??[]} lineupB={replay.resultJson?.lineupB??[]} onFinish={()=>setReplay(null)}/>}</>}

function RuleFields({form,setForm,presets,rewardPlans}:{form:any;setForm:(v:any)=>void;presets:Preset[];rewardPlans:RushRewardPlan[]}){
  const applyPreset=(id:string)=>{const p=presets.find(x=>x.id===id);if(!p)return;setForm({...form,preset:id,name:p.name,teamSize:p.teamSize,maxLevel:p.maxLevel,uniqueSpecies:p.uniqueSpecies,repeatMode:p.uniqueSpecies?"WEEKLY_UNIQUE":"UNRESTRICTED",requiredType:p.requiredType==="ROTATING"?"electric":p.requiredType??"",division:p.maxLevel<=45?"UNLIMITED":p.division??form.division});};
  return <div className="grid gap-3 md:grid-cols-3">
    <label className={labelClass}>Nome público da edição<input className={inputClass} value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label>
    {form.weekKey!==undefined&&<label className={labelClass}>Identificador único da semana<input className={inputClass} value={form.weekKey} onChange={e=>setForm({...form,weekKey:e.target.value})}/></label>}
    <label className={labelClass}>Modelo de regra<select className={inputClass} value={form.preset} onChange={e=>applyPreset(e.target.value)}>{presets.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>
    <label className={labelClass}>Divisão de mega evolução<select className={inputClass} value={form.division} onChange={e=>setForm({...form,division:e.target.value})}><option value="LIMITED">Limitado · até 2 megas</option><option value="UNLIMITED">Ilimitado · sem limite</option></select></label>
    <label className={labelClass}>Início da semana<input type="datetime-local" className={inputClass} value={form.weekStart} onChange={e=>setForm({...form,weekStart:e.target.value})}/></label>
    <label className={labelClass}>Fim da semana<input type="datetime-local" className={inputClass} value={form.weekEnd} onChange={e=>setForm({...form,weekEnd:e.target.value})}/></label>
    <div className="rounded-lg border border-slate-800 bg-slate-950 px-3 py-2 text-[10px] leading-relaxed text-slate-400"><strong className="block uppercase text-slate-300">Inscrições</strong>Encerram às 07:50 da segunda-feira. Às 08:00 a chave é gerada; com menos de 4 inscritos, a edição é cancelada.</div>
    <label className={labelClass}>Mascotes por equipe<input type="number" min={1} max={6} className={inputClass} value={form.teamSize} onChange={e=>setForm({...form,teamSize:Number(e.target.value)})}/></label>
    <label className={labelClass}>Nível máximo permitido<input type="number" min={1} className={inputClass} value={form.maxLevel} onChange={e=>setForm({...form,maxLevel:Number(e.target.value)})}/></label>
    <label className={labelClass}>Tipo obrigatório da semana<select className={inputClass} value={form.requiredType} onChange={e=>setForm({...form,requiredType:e.target.value})}><option value="">Todos os tipos</option>{Object.entries(TYPE_LABEL).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label>
    <label className={labelClass}>Regra de repetição<select className={inputClass} value={form.repeatMode} onChange={e=>setForm({...form,repeatMode:e.target.value,uniqueSpecies:e.target.value==="WEEKLY_UNIQUE"})}><option value="WEEKLY_UNIQUE">Não repete durante toda a semana</option><option value="DAILY_UNIQUE">Não repete no mesmo dia</option><option value="UNRESTRICTED">Pode repetir em todos os jogos</option></select></label>
    <label className={labelClass}>Personalidade obrigatória<select className={inputClass} value={form.requiredPersonality} onChange={e=>setForm({...form,requiredPersonality:e.target.value})}><option value="">Todas as personalidades</option>{Object.entries(PERSONALITY_LABEL).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label>
    <label className={labelClass}>Pacote de recompensas<select className={inputClass} value={form.rewardPlanId} onChange={e=>setForm({...form,rewardPlanId:e.target.value})}>{rewardPlans.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>
    <label className={labelClass}>Teto de referência da premiação<input type="number" min={1000} step={100} className={inputClass} value={form.rewardCap} onChange={e=>setForm({...form,rewardCap:Number(e.target.value)})}/></label>
    <p className="self-end rounded-lg border border-cyan-400/20 bg-cyan-400/5 px-3 py-2 text-[10px] leading-relaxed text-cyan-100">Semanas com tipo restrito tendem a permitir repetição e usar equipes menores, mas isso é uma tendência do sorteio, não uma obrigação.</p>
  </div>;
}

function AdminPanel({league,data,run,pending}:{league:League;data:Data;run:(job:()=>Promise<{error?:string;success?:boolean}>)=>void;pending:boolean}){
  const [date,setDate]=useState(new Date().toISOString().slice(0,10)); const rules=league.ruleJson??{};
  const [form,setForm]=useState({name:league.name,weekStart:localInput(league.weekStart),weekEnd:localInput(league.weekEnd),registrationEnds:localInput(league.registrationEnds),division:league.division,teamSize:league.teamSize,maxLevel:league.maxLevel??45,requiredType:league.requiredType??"",uniqueSpecies:league.uniqueSpecies,repeatMode:String(rules.repeatMode??(league.uniqueSpecies?"WEEKLY_UNIQUE":"UNRESTRICTED")),requiredPersonality:String(rules.requiredPersonality??""),preset:String(rules.preset??"RUSH_45"),rewardPlanId:String(rules.rewardPlanId??data.rewardPlan?.id??"VELOCIDADE"),rewardCap:Number(rules.rewardCap??6000)});
  const [editableRewards,setEditableRewards]=useState<RushRewardBundle[]>(data.rewards??[]);
  useEffect(()=>{const nextRules=league.ruleJson??{};setForm({name:league.name,weekStart:localInput(league.weekStart),weekEnd:localInput(league.weekEnd),registrationEnds:localInput(league.registrationEnds),division:league.division,teamSize:league.teamSize,maxLevel:league.maxLevel??45,requiredType:league.requiredType??"",uniqueSpecies:league.uniqueSpecies,repeatMode:String(nextRules.repeatMode??(league.uniqueSpecies?"WEEKLY_UNIQUE":"UNRESTRICTED")),requiredPersonality:String(nextRules.requiredPersonality??""),preset:String(nextRules.preset??"RUSH_45"),rewardPlanId:String(nextRules.rewardPlanId??data.rewardPlan?.id??"VELOCIDADE"),rewardCap:Number(nextRules.rewardCap??6000)});setEditableRewards(data.rewards??[]);},[league,data.rewards,data.rewardPlan?.id]);
  return <section className="rounded-2xl border border-purple-500/30 bg-purple-950/10 p-4"><h3 className="font-black text-purple-200">Gerenciamento da Rush</h3><p className="mt-1 text-xs text-slate-400">A rotação automática cria regras e prêmios diferentes. Aqui o admin pode sobrescrever qualquer detalhe, refazer o sorteio ou agendar outra semana.</p><div className="mt-4"><RuleFields form={form} setForm={setForm} presets={data.presets??[]} rewardPlans={data.rewardPlans??[]}/></div><div className="mt-3 flex flex-wrap gap-2"><button disabled={pending} onClick={()=>run(()=>adminUpdateRushLeagueAction({leagueId:league.id,...form,repeatMode:form.repeatMode as any}))} className="rounded-lg bg-purple-500 px-4 py-2 text-xs font-black text-white">Salvar regras da semana</button><button disabled={pending} onClick={()=>run(()=>adminRerollRushRulesAction(league.id))} className="rounded-lg border border-fuchsia-400/40 px-4 py-2 text-xs font-bold text-fuchsia-300">Sortear regras novamente</button><button disabled={pending} onClick={()=>run(()=>adminRegenerateRushRewardsAction(league.id,form.rewardPlanId,form.rewardCap))} className="rounded-lg border border-yellow-400/40 px-4 py-2 text-xs font-bold text-yellow-300">Refazer premiação pelo teto</button></div><div className="mt-5 border-t border-slate-800 pt-4"><h4 className="text-xs font-black text-white">Editar recompensas desta edição</h4><div className="mt-2 grid gap-2">{editableRewards.map((reward,index)=><div key={reward.key} className="grid gap-2 rounded-xl border border-slate-800 p-2 md:grid-cols-[120px_1fr_120px_110px]"><span className="self-center text-xs font-bold text-yellow-300">{rangeLabel(reward)}</span><input className={inputClass} value={reward.label} onChange={e=>setEditableRewards(rows=>rows.map((r,i)=>i===index?{...r,label:e.target.value}:r))}/><input title="ZC direto" type="number" className={inputClass} value={reward.coins??0} onChange={e=>setEditableRewards(rows=>rows.map((r,i)=>i===index?{...r,coins:Number(e.target.value)}:r))}/><input title="Valor estimado" type="number" className={inputClass} value={reward.estimatedValue} onChange={e=>setEditableRewards(rows=>rows.map((r,i)=>i===index?{...r,estimatedValue:Number(e.target.value)}:r))}/></div>)}</div><div className="mt-2 flex gap-2"><button disabled={pending} onClick={()=>run(()=>adminSaveRushRewardsAction(league.id,editableRewards,form.rewardCap,false))} className="rounded-lg bg-yellow-500 px-3 py-2 text-xs font-black text-slate-950">Salvar lista desta Rush</button><button disabled={pending} onClick={()=>run(()=>adminSaveRushRewardsAction(league.id,editableRewards,form.rewardCap,true))} className="rounded-lg border border-yellow-400/40 px-3 py-2 text-xs font-bold text-yellow-300">Salvar teto como padrão</button></div></div><div className="mt-5 flex flex-wrap items-end gap-2 border-t border-slate-800 pt-4"><label className={labelClass}>Dia a processar<input type="date" value={date} onChange={e=>setDate(e.target.value)} className={inputClass}/></label>{league.status==="REGISTRATION"&&<button disabled={pending} onClick={()=>run(()=>adminOpenRushLeagueAction(league.id))} className="rounded-lg bg-green-500 px-3 py-2 text-xs font-black text-slate-950">Encerrar inscrições e abrir</button>}<button disabled={pending} onClick={()=>run(()=>adminGenerateRushDayAction(league.id,date))} className="rounded-lg bg-cyan-500 px-3 py-2 text-xs font-black text-slate-950">Gerar as 3 partidas</button><button disabled={pending} onClick={()=>run(()=>adminRunRushDayAction(league.id,date))} className="rounded-lg bg-orange-400 px-3 py-2 text-xs font-black text-slate-950">Executar partidas prontas</button><button disabled={pending} onClick={()=>run(()=>adminFinishRushLeagueAction(league.id))} className="rounded-lg border border-red-400/40 px-3 py-2 text-xs font-bold text-red-300">Finalizar e enviar caixas</button></div></section>;
}

function CreatePanel({data,run,pending}:{data:Data;run:(job:()=>Promise<{error?:string;success?:boolean}>)=>void;pending:boolean}){
  const nextMonday=useMemo(()=>{const d=new Date();d.setDate(d.getDate()+((8-d.getDay())%7||7));return d.toISOString().slice(0,10)},[]);
  const [form,setForm]=useState({name:"Rush Nv.45",weekKey:`RUSH-${nextMonday}`,weekStart:`${nextMonday}T00:00`,weekEnd:`${addDaysIso(nextMonday,4)}T19:30`,registrationEnds:`${nextMonday}T07:50`,division:"UNLIMITED",teamSize:3,maxLevel:45,requiredType:"",uniqueSpecies:false,repeatMode:"UNRESTRICTED",requiredPersonality:"",preset:"RUSH_45",rewardPlanId:"VELOCIDADE",rewardCap:6000});
  const selectedPlan=(data.rewardPlans??[]).find(p=>p.id===form.rewardPlanId);
  return <section className="rounded-2xl border border-purple-500/30 bg-purple-950/10 p-4"><h2 className="font-black text-purple-200">Agendar nova edição Rush</h2><p className="mt-1 text-xs text-slate-400">Use uma segunda-feira no início e a sexta-feira correspondente no fim. As inscrições encerram às 07:50 da segunda-feira; a chave é gerada às 08:00.</p><div className="mt-4"><RuleFields form={form} setForm={setForm} presets={data.presets??[]} rewardPlans={data.rewardPlans??[]}/></div>{selectedPlan&&<div className="mt-3 rounded-xl border border-yellow-400/20 bg-yellow-400/5 p-3 text-xs text-slate-300"><strong className="text-yellow-300">Prévia: {selectedPlan.name}</strong><p className="mt-1">{selectedPlan.bundles.map(b=>`${rangeLabel(b)}: ${b.label}`).join(" · ")}</p></div>}<button disabled={pending} onClick={()=>run(()=>adminCreateRushLeagueAction({...form,repeatMode:form.repeatMode as any}))} className="mt-4 rounded-xl bg-purple-500 px-5 py-2 text-xs font-black text-white">Agendar edição e abrir inscrições</button></section>;
}

function RushTeamDebugger({league,mascots}:{league:League;mascots:Mascot[]}){const [ids,setIds]=useState<string[]>([]);const [result,setResult]=useState<{valid:boolean;checks:Array<{label:string;valid:boolean;detail:string}>}|null>(null);const [pending,start]=useTransition();return <section className="rounded-2xl border border-cyan-500/30 bg-cyan-950/10 p-4"><h3 className="font-black text-cyan-200">Debug de montagem de equipe</h3><p className="mt-1 text-xs text-slate-400">Selecione de 1 até {league.teamSize} mascotes da sua conta administrativa. Nada será salvo: o servidor apenas testa as regras atuais.</p><div className="mt-3 grid max-h-64 gap-2 overflow-y-auto sm:grid-cols-2 lg:grid-cols-3">{mascots.map(m=><label key={m.id} className={`flex cursor-pointer items-center gap-2 rounded-lg border p-2 text-xs ${ids.includes(m.id)?"border-cyan-400 bg-cyan-400/10":"border-slate-800"}`}><input type="checkbox" checked={ids.includes(m.id)} onChange={()=>setIds(current=>current.includes(m.id)?current.filter(id=>id!==m.id):current.length<league.teamSize?[...current,m.id]:current)}/><span><strong className="text-white">{m.name} · Nv.{m.level}</strong><small className="block text-slate-500">{m.types.map(t=>TYPE_LABEL[t]??t).join(" / ")} · {PERSONALITY_LABEL[m.personality]??m.personality}</small></span></label>)}</div><button disabled={pending||ids.length<1} onClick={()=>start(async()=>{const response=await adminDebugRushTeamAction(league.id,ids);if(response.error)toast.error(response.error);else setResult(response as typeof result);})} className="mt-3 rounded-lg bg-cyan-500 px-4 py-2 text-xs font-black text-slate-950 disabled:opacity-40">Testar equipe sem salvar</button>{result&&<div className={`mt-3 rounded-xl border p-3 ${result.valid?"border-green-400/30 bg-green-400/5":"border-red-400/30 bg-red-400/5"}`}><p className={`text-xs font-black ${result.valid?"text-green-300":"text-red-300"}`}>{result.valid?"Equipe válida":"Equipe inválida"}</p><div className="mt-2 grid gap-1 md:grid-cols-2">{result.checks.map(check=><p key={check.label} className="text-[11px] text-slate-300"><strong className={check.valid?"text-green-300":"text-red-300"}>{check.valid?"✓":"✕"} {check.label}:</strong> {check.detail}</p>)}</div></div>}</section>}

function RushManual({presets}:{presets:Preset[]}){return <section className={cardClass}><div className="flex items-start gap-3"><Sparkles className="mt-0.5 text-orange-300"/><div><h3 className="font-black text-white">Manual da Liga Rush</h3><p className="mt-1 text-xs leading-relaxed text-slate-400">A Rush é uma liga semanal opcional e gratuita. Como na Liga Semanal, os inscritos montam equipes para três confrontos por dia; a diferença é que as equipes são menores, o ritmo é mais rápido e a regra principal muda de uma semana para outra.</p></div></div><div className="mt-4 grid gap-3 md:grid-cols-3"><ManualStep title="1. Inscrição e chave" text="Inscrição e cancelamento ficam disponíveis até segunda-feira, 07:50. Às 08:00, a chave é revelada. O servidor só aceita equipes compatíveis com todas as regras ativas."/><ManualStep title="2. Rodadas do dia" text="Os combates acontecem às 19:00, 19:10 e 19:20. Vitória vale 3 pontos, empate 1 e derrota 0. Sobreviventes, dano causado e menor dano recebido ajudam no desempate."/><ManualStep title="3. Premiação e participação" text="Às 19:30 a rodada é encerrada. As caixas da semana ficam visíveis antes da disputa. Como presente inaugural da Rush, todos os jogadores também receberam 3 Ovos Raros de participação."/></div><h4 className="mt-5 text-xs font-black uppercase tracking-wide text-orange-300">Exemplos de semanas</h4><div className="mt-2 grid gap-2 md:grid-cols-2 xl:grid-cols-3">{presets.map(p=><div key={p.id} className="rounded-xl border border-slate-800 p-3"><strong className="text-xs text-white">{p.name}</strong><p className="mt-1 text-[11px] leading-relaxed text-slate-500">{p.description}</p></div>)}</div><div className="mt-4 grid gap-2 md:grid-cols-2"><p className="rounded-xl border border-cyan-400/20 bg-cyan-400/5 p-3 text-[11px] leading-relaxed text-cyan-100"><strong>Rotação semanal:</strong> nível, tamanho da equipe, tipo, personalidade, repetição, divisão e prêmios podem mudar. Em semanas monotipo, o sorteio tende — sem obrigação — a usar equipes menores e repetição mais flexível.</p><p className="rounded-xl border border-orange-400/20 bg-orange-400/5 p-3 text-[11px] leading-relaxed text-orange-100"><strong>Limitado e Ilimitado:</strong> Limitado aceita no máximo 2 Megas por equipe. Ilimitado não restringe Megas. Toda regra automática com nível máximo 45 é sempre Ilimitada, pois mega evolução só começa no nível 50.</p></div></section>}
function ManualStep({title,text}:{title:string;text:string}){return <div className="rounded-xl border border-slate-800 bg-slate-900/40 p-3"><strong className="text-xs text-white">{title}</strong><p className="mt-1 text-[11px] leading-relaxed text-slate-500">{text}</p></div>}
function DivisionTable(){return <section className={cardClass}><h3 className="font-black text-white">Padrão oficial de divisões</h3><p className="mt-1 text-xs text-slate-400">Limitado controla a quantidade de mega evoluções; Ilimitado aceita qualquer composição. A Rush informa a divisão escolhida em cada edição.</p><div className="mt-3 grid gap-2 md:grid-cols-2">{OFFICIAL_BATTLE_DIVISION_MODES.map(row=><div key={row.mode} className="rounded-xl border border-slate-800 p-3"><div className="flex justify-between gap-3"><strong className="text-xs text-white">{row.mode}</strong><span className="text-[10px] font-black uppercase text-cyan-300">{row.division}</span></div><p className="mt-1 text-[10px] leading-relaxed text-slate-500">{row.detail}</p></div>)}</div></section>}
